#!/usr/bin/env node
// Regenerates src/lib/pageRevisions.ts from git history.
//
//   node scripts/gen-page-revisions.mjs
//
// Run this after editing any hand-authored page (the ones in TOOL_PATHS or
// INFO_PATHS) and commit the result alongside the edit.
//
// Why a generated file instead of reading git at build time: Vercel builds from
// a shallow clone, so `git log -- <path>` there returns nothing for any file not
// touched in the last few commits. Committing the dates is the only way the
// build can see them. Why generated instead of hand-maintained: a hand-kept map
// goes stale silently, which is exactly the failure this replaces.

import { execFileSync } from 'node:child_process';
import { existsSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = resolve(ROOT, 'src/lib/pageRevisions.ts');

// Read the route lists straight from the TS source so the two can't drift.
const routesSrc = execFileSync('cat', [resolve(ROOT, 'src/lib/sitemapRoutes.ts')], { encoding: 'utf8' });
const readList = (name) => {
  const body = routesSrc.match(new RegExp(`export const ${name} = \\[([\\s\\S]*?)\\]`))?.[1] ?? '';
  return [...body.matchAll(/'([^']*)'/g)].map((m) => m[1]).filter(Boolean);
};

const paths = [...readList('TOOL_PATHS'), ...readList('INFO_PATHS')];
if (paths.length === 0) {
  console.error('No routes found in src/lib/sitemapRoutes.ts — aborting rather than writing an empty map.');
  process.exit(1);
}

const lastCommitDate = (file) => {
  try {
    const out = execFileSync('git', ['log', '-1', '--format=%cs', '--', file], { cwd: ROOT, encoding: 'utf8' }).trim();
    return out || null;
  } catch {
    return null;
  }
};

const entries = [];
const missing = [];
for (const p of paths) {
  const file = `src/app/[locale]${p}/page.tsx`;
  if (!existsSync(resolve(ROOT, file))) {
    missing.push(`${p} (no ${file})`);
    continue;
  }
  const date = lastCommitDate(file);
  if (!date) {
    missing.push(`${p} (no commit touching ${file} — shallow clone?)`);
    continue;
  }
  entries.push([p, date]);
}

// Data files that back generated pages but aren't routes themselves.
for (const [key, file] of [['glossary', 'src/lib/glossary.ts'], ['aiGlossary', 'src/lib/aiGlossary.ts']]) {
  const date = lastCommitDate(file);
  if (date) entries.push([key, date]);
  else missing.push(`${key} (no commit touching ${file})`);
}

const body = entries.map(([k, v]) => `  '${k}': '${v}',`).join('\n');
writeFileSync(
  OUT,
  `// GENERATED by scripts/gen-page-revisions.mjs — do not edit by hand.\n` +
    `// Last commit date of each hand-authored page's source, used as its sitemap\n` +
    `// lastmod. Regenerate after editing any of these pages:\n` +
    `//   node scripts/gen-page-revisions.mjs\n\n` +
    `export const PAGE_REVISIONS: Record<string, string> = {\n${body}\n};\n`,
  'utf8'
);

console.log(`Wrote ${entries.length} revision dates to src/lib/pageRevisions.ts`);
if (missing.length) {
  console.warn(`\nSkipped ${missing.length}:`);
  for (const m of missing) console.warn(`  - ${m}`);
}
